var BASE_FONT_SIZE=16,REFERENCE_SIZE=500,SCALING_EXPONENT=5/6,MIN_FONT_SIZE=12,MAX_FONT_SIZE=120,getScaledFontSize=function(a,b){if(!a||!b)return BASE_FONT_SIZE;var c=Math.round(BASE_FONT_SIZE*Math.pow((a+b)/2/REFERENCE_SIZE,SCALING_EXPONENT));return Math.max(MIN_FONT_SIZE,Math.min(MAX_FONT_SIZE,c))};export default getScaledFontSize;